static unsigned mask = 022;

unsigned SetMask(unsigned next) {
  unsigned old = mask;
  mask = next & 0777;
  return old;
}

struct Context { unsigned mask; };

unsigned SetMask(struct Context *ctx,
                 unsigned next) {
  unsigned old = ctx->mask;
  ctx->mask = next & 0777;
  return old;
}
